{"tool":"codemode","args":{"code":"const result = await tools.browser_navigate({url: 'https://example.com/production-browser-record'});
const snapshot = await tools.browser_snapshot({});
const elements = unwrap(snapshot).elements;

// Find Locality input
const localityInput = elements.find(e => e.name === 'Locality' || e.role === 'textbox' && e.name === 'Locality');
// If name is not exact, find by role and look for 'Locality' in name or value
const localityRef = elements.find(e => e.name === 'Locality' || (e.role === 'textbox' && e.name.includes('Locality')))?.ref;

if (localityRef) {
  await tools.browser_fill({ref: localityRef, value: '福州'});

  // Re-snapshot because old ref might be stale
  const newSnapshot = await tools.browser_snapshot({});
  const newElements = unwrap(newSnapshot).elements;

  // Find Load record button
  const loadRecordRef = newElements.find(e => e.name === 'Load record' || e.name === 'Load')?.ref;

  if (loadRecordRef) {
    await tools.browser_click({ref: loadRecordRef});

    // Wait for 鱼丸 (fish ball) to appear
    await tools.browser_wait({condition: 'text', value: '鱼丸', timeout_ms: 5000});

    // Read current page
    const pageText = await tools.browser_read({});
    return unwrap(pageText);
  }
} else {
  return 'Locality input not found';
}

// Get script token
const tokenResult = await tools.browser_eval({code: 'window.__contractToken'});
const token = unwrap(tokenResult).value;

// Get current tab URL
const tabList = await tools.browser_tab_list({});
const currentUrl = unwrap(tabList).page_url;

return {token, currentUrl};
